; t05_peri -- Peri: EXEC_CSR, BR, EXEC_PUB
; Layer-3 timing program (generated by conformance/make_timing.py: edit that, not this file).
; Markers are CSR writes to RES + k; the intervals between them are what is measured. Predictions: TIMING.md
.include "conf_defs.inc"
.service SID_T = 5
.peri
.assume PERI_RX_BUF[0..31] defined
    EXEC_CSR WRITE8 RES + 16, 0x50            ; marker 16
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 17, 0x51            ; marker 17
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 65, 0x01
    EXEC_CSR WRITE8 RES + 18, 0x52            ; marker 18
    EXEC_CSR WRITE8 RES + 19, 0x53            ; marker 19
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    EXEC_CSR WRITE8 RES + 20, 0x54            ; marker 20
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    BR.IF_ERROR pnever
    EXEC_CSR WRITE8 RES + 21, 0x55            ; marker 21
    EXEC_CSR WRITE8 RES + 22, 0x56            ; marker 22
    EXEC_PUB service=SID_T, src=0, len=1
    EXEC_PUB service=SID_T, src=0, len=1
    EXEC_CSR WRITE8 RES + 23, 0x57            ; marker 23
    EXEC_PUB service=SID_T, src=0, len=1
    EXEC_PUB service=SID_T, src=0, len=1
    EXEC_PUB service=SID_T, src=0, len=1
    EXEC_PUB service=SID_T, src=0, len=1
    EXEC_PUB service=SID_T, src=0, len=1
    EXEC_PUB service=SID_T, src=0, len=1
    EXEC_CSR WRITE8 RES + 24, 0x58            ; marker 24
    EXEC_CSR WRITE8 RES + 25, 0x59            ; marker 25
    EXEC_PUB service=SID_T, src=0, len=8
    EXEC_PUB service=SID_T, src=0, len=8
    EXEC_CSR WRITE8 RES + 26, 0x5A            ; marker 26
    EXEC_PUB service=SID_T, src=0, len=8
    EXEC_PUB service=SID_T, src=0, len=8
    EXEC_PUB service=SID_T, src=0, len=8
    EXEC_PUB service=SID_T, src=0, len=8
    EXEC_PUB service=SID_T, src=0, len=8
    EXEC_PUB service=SID_T, src=0, len=8
    EXEC_CSR WRITE8 RES + 27, 0x5B            ; marker 27
    JMP ppast
pnever:
    EXEC_CSR WRITE8 RES + 31, 0xBD           ; (never reached)
ppast:
    EXEC_CSR WRITE8 RES_DONE, 0xA5
pdone:
    JMP pdone
